import{_ as i,V as l,W as c,Z as a,Y as n,a0 as s,X as p,F as e}from"./framework-9f272d12.js";const r={},u=p('<h1 id="agent-高频面试·第二篇-工具执行失败-你能答到第几层" tabindex="-1"><a class="header-anchor" href="#agent-高频面试·第二篇-工具执行失败-你能答到第几层" aria-hidden="true">#</a> Agent 高频面试·第二篇：工具执行失败，你能答到第几层？</h1><figure><img src="https://imgbed.ppai.top/file/1777163055013_m2-cover.jpeg" alt="m2-cover.jpeg" tabindex="0" loading="lazy"><figcaption>m2-cover.jpeg</figcaption></figure><h2 id="_1-引言" tabindex="-1"><a class="header-anchor" href="#_1-引言" aria-hidden="true">#</a> 1. 引言</h2><p>在 Agent 系统开发的面试中，<strong>工具执行失败的处理</strong>是一个极高频的考察点。这道题看似简单——不就是 try-catch 吗？——但实际上，传统编程的错误处理思路在 Agent 场景下完全不适用。</p><figure><img src="https://imgbed.ppai.top/file/1777162284766_m2-01.jpeg" alt="m2-01.jpeg" tabindex="0" loading="lazy"><figcaption>m2-01.jpeg</figcaption></figure><p>本文从面试官视角，系统性地解析这道题的考察层次、问题本质、解决方案，以及如何在面试中展现自己的深度。</p><h2 id="_2-面试高频问题" tabindex="-1"><a class="header-anchor" href="#_2-面试高频问题" aria-hidden="true">#</a> 2. 面试高频问题</h2><h3 id="_2-1-典型面试问题" tabindex="-1"><a class="header-anchor" href="#_2-1-典型面试问题" aria-hidden="true">#</a> 2.1 典型面试问题</h3><p>在 Agent 开发岗位的面试中，面试官通常会通过以下方式考察这个问题：</p><figure><img src="https://imgbed.ppai.top/file/1777162286659_m2-05.jpeg" alt="m2-05.jpeg" tabindex="0" loading="lazy"><figcaption>m2-05.jpeg</figcaption></figure><p><strong>初级问题</strong>：</p><ul><li>“如果工具调用返回了 500 错误，Agent 应该如何处理？”</li><li>“LLM 收到错误信息后，它会怎么行动？”</li></ul><p><strong>进阶问题</strong>：</p><ul><li>“为什么模型会把错误结果解读成成功？”</li><li>“参数格式不匹配时，LLM 修复参数为什么会越修越错？”</li><li>“重试策略应该由模型控制还是系统控制？”</li></ul><p><strong>深度问题</strong>：</p><ul><li>“连续失败多少次后应该终止流程？为什么是这个数字？”</li><li>“如何设计错误信息，让 LLM 能正确理解并做出合理决策？”</li><li>“多工具组合时，其中一个工具失败了，整个任务应该如何处理？”</li></ul><h3 id="_2-2-面试官的考察点" tabindex="-1"><a class="header-anchor" href="#_2-2-面试官的考察点" aria-hidden="true">#</a> 2.2 面试官的考察点</h3><figure><img src="https://imgbed.ppai.top/file/1777162297033_m2-06.jpeg" alt="m2-06.jpeg" tabindex="0" loading="lazy"><figcaption>m2-06.jpeg</figcaption></figure><table><thead><tr><th>考察维度</th><th>面试官想看到的</th></tr></thead><tbody><tr><td>问题理解</td><td>能否清晰描述 Agent 场景下错误处理的特殊性</td></tr><tr><td>方案设计</td><td>能否提出分层解决方案（工具层、系统层、LLM层）</td></tr><tr><td>工程实现</td><td>能否给出具体的重试策略、错误校验代码设计</td></tr><tr><td>权衡思维</td><td>能否认识到用户体验与系统资源的权衡</td></tr><tr><td>边界考虑</td><td>能否考虑到连续失败、多工具组合等边界情况</td></tr></tbody></table><h2 id="_3-问题本质" tabindex="-1"><a class="header-anchor" href="#_3-问题本质" aria-hidden="true">#</a> 3. 问题本质</h2><h3 id="_3-1-核心矛盾" tabindex="-1"><a class="header-anchor" href="#_3-1-核心矛盾" aria-hidden="true">#</a> 3.1 核心矛盾</h3>',21),d=p(`<p><strong>核心矛盾</strong>：传统编程中，代码明确知道失败并可预测处理；而在 Agent 场景中，LLM 需要&quot;理解&quot;错误文本后决定下一步，这个过程不可预测。</p><figure><img src="https://imgbed.ppai.top/file/1777162281403_m2-02.jpeg" alt="m2-02.jpeg" tabindex="0" loading="lazy"><figcaption>m2-02.jpeg</figcaption></figure><h3 id="_3-2-问题量化分析" tabindex="-1"><a class="header-anchor" href="#_3-2-问题量化分析" aria-hidden="true">#</a> 3.2 问题量化分析</h3><table><thead><tr><th>维度</th><th>传统编程</th><th>Agent 场景</th></tr></thead><tbody><tr><td>失败感知确定性</td><td>代码明确知道失败</td><td>LLM 收到的只是文本</td></tr><tr><td>失败处理可预测性</td><td>try-catch 明确捕获</td><td>LLM 可能忽略、误解、或过度重试</td></tr><tr><td>重试控制</td><td>开发者完全控制</td><td>模型控制或系统控制</td></tr></tbody></table><h2 id="_4-方案对比" tabindex="-1"><a class="header-anchor" href="#_4-方案对比" aria-hidden="true">#</a> 4. 方案对比</h2><figure><img src="https://imgbed.ppai.top/file/1777162281577_m2-03.jpeg" alt="m2-03.jpeg" tabindex="0" loading="lazy"><figcaption>m2-03.jpeg</figcaption></figure><h3 id="_4-1-方案一-参数自动转换" tabindex="-1"><a class="header-anchor" href="#_4-1-方案一-参数自动转换" aria-hidden="true">#</a> 4.1 方案一：参数自动转换</h3><p>在工具层实现参数标准化，减少 LLM 的猜测空间。</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">class</span> <span class="token class-name">WeatherTool</span><span class="token punctuation">:</span>
    <span class="token keyword">def</span> <span class="token function">__init__</span><span class="token punctuation">(</span>self<span class="token punctuation">)</span><span class="token punctuation">:</span>
        self<span class="token punctuation">.</span>param_mapping <span class="token operator">=</span> <span class="token punctuation">{</span>
            <span class="token string">&quot;city&quot;</span><span class="token punctuation">:</span> <span class="token string">&quot;city_name&quot;</span><span class="token punctuation">,</span>
            <span class="token string">&quot;c&quot;</span><span class="token punctuation">:</span> <span class="token string">&quot;city_name&quot;</span>
        <span class="token punctuation">}</span>
        self<span class="token punctuation">.</span>city_normalization <span class="token operator">=</span> <span class="token punctuation">{</span>
            <span class="token string">&quot;北京&quot;</span><span class="token punctuation">:</span> <span class="token string">&quot;beijing&quot;</span><span class="token punctuation">,</span>
            <span class="token string">&quot;上海&quot;</span><span class="token punctuation">:</span> <span class="token string">&quot;shanghai&quot;</span>
        <span class="token punctuation">}</span>
    
    <span class="token keyword">def</span> <span class="token function">normalize_params</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> params<span class="token punctuation">:</span> <span class="token builtin">dict</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">dict</span><span class="token punctuation">:</span>
        normalized <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
        <span class="token keyword">for</span> key<span class="token punctuation">,</span> value <span class="token keyword">in</span> params<span class="token punctuation">.</span>items<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
            mapped_key <span class="token operator">=</span> self<span class="token punctuation">.</span>param_mapping<span class="token punctuation">.</span>get<span class="token punctuation">(</span>key<span class="token punctuation">,</span> key<span class="token punctuation">)</span>
            <span class="token keyword">if</span> key <span class="token operator">==</span> <span class="token string">&quot;city&quot;</span> <span class="token keyword">and</span> value <span class="token keyword">in</span> self<span class="token punctuation">.</span>city_normalization<span class="token punctuation">:</span>
                value <span class="token operator">=</span> self<span class="token punctuation">.</span>city_normalization<span class="token punctuation">[</span>value<span class="token punctuation">]</span>
            normalized<span class="token punctuation">[</span>mapped_key<span class="token punctuation">]</span> <span class="token operator">=</span> value
        <span class="token keyword">return</span> normalized
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>优点</strong>：</p><ul><li>减少 LLM 的参数生成负担</li><li>提升工具调用成功率</li><li>实现相对简单</li></ul><p><strong>缺点</strong>：</p><ul><li>增加工具层的复杂性</li><li>可能掩盖 API 设计问题</li><li>需要维护映射表</li></ul><p><strong>适用场景</strong>：工具参数格式不统一、LLM 生成参数容易出错的场景。</p><h3 id="_4-2-方案二-强化结果校验层" tabindex="-1"><a class="header-anchor" href="#_4-2-方案二-强化结果校验层" aria-hidden="true">#</a> 4.2 方案二：强化结果校验层</h3><p>在工具返回和 LLM 输入之间增加校验层，明确区分成功与失败。</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">class</span> <span class="token class-name">ToolResultValidator</span><span class="token punctuation">:</span>
    <span class="token keyword">def</span> <span class="token function">validate</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> result<span class="token punctuation">:</span> ToolResult<span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> ValidationResult<span class="token punctuation">:</span>
        <span class="token keyword">if</span> result<span class="token punctuation">.</span>is_success<span class="token punctuation">:</span>
            <span class="token keyword">return</span> ValidationResult<span class="token punctuation">(</span>valid<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">,</span> action<span class="token operator">=</span><span class="token string">&quot;continue&quot;</span><span class="token punctuation">)</span>
        
        <span class="token keyword">if</span> self<span class="token punctuation">.</span>is_retryable_error<span class="token punctuation">(</span>result<span class="token punctuation">.</span>error<span class="token punctuation">)</span><span class="token punctuation">:</span>
            <span class="token keyword">return</span> ValidationResult<span class="token punctuation">(</span>
                valid<span class="token operator">=</span><span class="token boolean">False</span><span class="token punctuation">,</span>
                action<span class="token operator">=</span><span class="token string">&quot;retry&quot;</span><span class="token punctuation">,</span>
                reason<span class="token operator">=</span>result<span class="token punctuation">.</span>error<span class="token punctuation">.</span>message
            <span class="token punctuation">)</span>
        
        <span class="token keyword">return</span> ValidationResult<span class="token punctuation">(</span>
            valid<span class="token operator">=</span><span class="token boolean">False</span><span class="token punctuation">,</span>
            action<span class="token operator">=</span><span class="token string">&quot;fail&quot;</span><span class="token punctuation">,</span>
            error_message<span class="token operator">=</span>self<span class="token punctuation">.</span>format_error<span class="token punctuation">(</span>result<span class="token punctuation">.</span>error<span class="token punctuation">)</span>
        <span class="token punctuation">)</span>
    
    <span class="token keyword">def</span> <span class="token function">is_retryable_error</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> error<span class="token punctuation">:</span> Error<span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">bool</span><span class="token punctuation">:</span>
        <span class="token keyword">return</span> error<span class="token punctuation">.</span>code <span class="token keyword">in</span> <span class="token punctuation">[</span><span class="token number">500</span><span class="token punctuation">,</span> <span class="token number">502</span><span class="token punctuation">,</span> <span class="token number">503</span><span class="token punctuation">,</span> <span class="token number">504</span><span class="token punctuation">]</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>优点</strong>：</p><ul><li>明确区分成功与失败状态</li><li>减少 LLM 误解错误的可能性</li><li>可根据错误类型决定重试策略</li></ul><p><strong>缺点</strong>：</p><ul><li>需要为每个工具定义错误处理逻辑</li><li>可能无法覆盖所有错误类型</li></ul><p><strong>适用场景</strong>：需要明确错误状态、避免 LLM 误解错误的场景。</p><h3 id="_4-3-方案三-重试策略系统控制-推荐" tabindex="-1"><a class="header-anchor" href="#_4-3-方案三-重试策略系统控制-推荐" aria-hidden="true">#</a> 4.3 方案三：重试策略系统控制（推荐）</h3><p>系统层控制重试策略，LLM 只负责决定是否重试已经修复过的问题。</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">class</span> <span class="token class-name">RetryableToolExecutor</span><span class="token punctuation">:</span>
    <span class="token keyword">def</span> <span class="token function">__init__</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> max_retry<span class="token punctuation">:</span> <span class="token builtin">int</span> <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
        self<span class="token punctuation">.</span>max_retry <span class="token operator">=</span> max_retry
    
    <span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">execute_with_retry</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> tool<span class="token punctuation">:</span> Tool<span class="token punctuation">,</span> params<span class="token punctuation">:</span> <span class="token builtin">dict</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
        <span class="token keyword">for</span> attempt <span class="token keyword">in</span> <span class="token builtin">range</span><span class="token punctuation">(</span>self<span class="token punctuation">.</span>max_retry <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
            result <span class="token operator">=</span> <span class="token keyword">await</span> tool<span class="token punctuation">.</span>execute<span class="token punctuation">(</span>params<span class="token punctuation">)</span>
            <span class="token keyword">if</span> result<span class="token punctuation">.</span>is_success<span class="token punctuation">:</span>
                <span class="token keyword">return</span> result
            
            <span class="token keyword">if</span> <span class="token keyword">not</span> self<span class="token punctuation">.</span>is_retryable<span class="token punctuation">(</span>result<span class="token punctuation">.</span>error<span class="token punctuation">)</span><span class="token punctuation">:</span>
                <span class="token keyword">return</span> self<span class="token punctuation">.</span>format_failure_result<span class="token punctuation">(</span>result<span class="token punctuation">.</span>error<span class="token punctuation">)</span>
        
        <span class="token keyword">return</span> self<span class="token punctuation">.</span>format_failure_result<span class="token punctuation">(</span>
            <span class="token string-interpolation"><span class="token string">f&quot;工具执行失败，已重试 </span><span class="token interpolation"><span class="token punctuation">{</span>self<span class="token punctuation">.</span>max_retry<span class="token punctuation">}</span></span><span class="token string"> 次&quot;</span></span>
        <span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>优点</strong>：</p><ul><li>重试行为确定、可控</li><li>可精确限制重试次数</li><li>避免 LLM 反复重试失败操作</li></ul><p><strong>缺点</strong>：</p><ul><li>灵活性差，可能错过可恢复的错误</li><li>需要为不同错误类型定义不同策略</li></ul><p><strong>适用场景</strong>：<strong>推荐用于生产环境</strong>，需要确定性强、重试行为可控的场景。</p><h3 id="_4-4-方案四-连续失败终止机制" tabindex="-1"><a class="header-anchor" href="#_4-4-方案四-连续失败终止机制" aria-hidden="true">#</a> 4.4 方案四：连续失败终止机制</h3><figure><img src="https://imgbed.ppai.top/file/1777162282329_m2-04.jpeg" alt="m2-04.jpeg" tabindex="0" loading="lazy"><figcaption>m2-04.jpeg</figcaption></figure><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">class</span> <span class="token class-name">FailureTracker</span><span class="token punctuation">:</span>
    <span class="token keyword">def</span> <span class="token function">__init__</span><span class="token punctuation">(</span>
        self<span class="token punctuation">,</span>
        max_consecutive_failures<span class="token punctuation">:</span> <span class="token builtin">int</span> <span class="token operator">=</span> <span class="token number">3</span><span class="token punctuation">,</span>
        failure_window<span class="token punctuation">:</span> <span class="token builtin">int</span> <span class="token operator">=</span> <span class="token number">300</span>
    <span class="token punctuation">)</span><span class="token punctuation">:</span>
        self<span class="token punctuation">.</span>max_consecutive_failures <span class="token operator">=</span> max_consecutive_failures
        self<span class="token punctuation">.</span>failure_history<span class="token punctuation">:</span> <span class="token builtin">list</span><span class="token punctuation">[</span>FailureRecord<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
    
    <span class="token keyword">def</span> <span class="token function">should_terminate</span><span class="token punctuation">(</span>self<span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">bool</span><span class="token punctuation">:</span>
        recent_failures <span class="token operator">=</span> self<span class="token punctuation">.</span>get_recent_failures<span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token keyword">return</span> <span class="token builtin">len</span><span class="token punctuation">(</span>recent_failures<span class="token punctuation">)</span> <span class="token operator">&gt;=</span> self<span class="token punctuation">.</span>max_consecutive_failures
    
    <span class="token keyword">def</span> <span class="token function">get_recent_failures</span><span class="token punctuation">(</span>self<span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">list</span><span class="token punctuation">[</span>FailureRecord<span class="token punctuation">]</span><span class="token punctuation">:</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            f <span class="token keyword">for</span> f <span class="token keyword">in</span> self<span class="token punctuation">.</span>failure_history
            <span class="token keyword">if</span> f<span class="token punctuation">.</span>timestamp <span class="token operator">&gt;</span> time<span class="token punctuation">.</span>time<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span> self<span class="token punctuation">.</span>failure_window
        <span class="token punctuation">]</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>为什么是 3 次</strong>：</p><ul><li><strong>用户体验</strong>：用户等待时间不宜超过合理范围（网络请求通常 ms 级，3 次重试意味着数秒到十数秒的等待）</li><li><strong>资源保护</strong>：防止无限重试被滥用，消耗系统资源</li><li><strong>统计意义</strong>：连续 3 次失败通常意味着系统性问题，单次重试难以解决</li></ul><h3 id="_4-5-方案对比总结" tabindex="-1"><a class="header-anchor" href="#_4-5-方案对比总结" aria-hidden="true">#</a> 4.5 方案对比总结</h3><table><thead><tr><th>维度</th><th>参数自动转换</th><th>结果校验层</th><th>系统控制重试</th><th>失败终止机制</th></tr></thead><tbody><tr><td>解决位置</td><td>工具层</td><td>系统层</td><td>系统层</td><td>系统层</td></tr><tr><td>解决对象</td><td>参数错误</td><td>状态误判</td><td>过度重试</td><td>无限循环</td></tr><tr><td>实现复杂度</td><td>中</td><td>低</td><td>中</td><td>低</td></tr><tr><td>重要性</td><td>高</td><td>高</td><td><strong>高</strong></td><td>高</td></tr></tbody></table><h2 id="_5-深入入问题解析" tabindex="-1"><a class="header-anchor" href="#_5-深入入问题解析" aria-hidden="true">#</a> 5. 深入入问题解析</h2><h3 id="_5-1-错误信息的结构化设计" tabindex="-1"><a class="header-anchor" href="#_5-1-错误信息的结构化设计" aria-hidden="true">#</a> 5.1 错误信息的结构化设计</h3><p>为了让 LLM 正确理解错误，错误信息应该结构化：</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">class</span> <span class="token class-name">ToolError</span><span class="token punctuation">:</span>
    <span class="token keyword">def</span> <span class="token function">__init__</span><span class="token punctuation">(</span>
        self<span class="token punctuation">,</span>
        error_type<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span>
        error_message<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span>
        error_code<span class="token punctuation">:</span> <span class="token builtin">int</span><span class="token punctuation">,</span>
        fix_suggestion<span class="token punctuation">:</span> <span class="token builtin">str</span> <span class="token operator">|</span> <span class="token boolean">None</span> <span class="token operator">=</span> <span class="token boolean">None</span><span class="token punctuation">,</span>
        can_retry<span class="token punctuation">:</span> <span class="token builtin">bool</span> <span class="token operator">=</span> <span class="token boolean">False</span>
    <span class="token punctuation">)</span><span class="token punctuation">:</span>
        self<span class="token punctuation">.</span>error_type <span class="token operator">=</span> error_type
        self<span class="token punctuation">.</span>error_code <span class="token operator">=</span> error_code
        self<span class="token punctuation">.</span>fix_suggestion <span class="token operator">=</span> fix_suggestion
        self<span class="token punctuation">.</span>can_retry <span class="token operator">=</span> can_retry
    
    <span class="token keyword">def</span> <span class="token function">to_message</span><span class="token punctuation">(</span>self<span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">str</span><span class="token punctuation">:</span>
        parts <span class="token operator">=</span> <span class="token punctuation">[</span>
            <span class="token string-interpolation"><span class="token string">f&quot;错误类型: </span><span class="token interpolation"><span class="token punctuation">{</span>self<span class="token punctuation">.</span>error_type<span class="token punctuation">}</span></span><span class="token string">&quot;</span></span><span class="token punctuation">,</span>
            <span class="token string-interpolation"><span class="token string">f&quot;错误代码: </span><span class="token interpolation"><span class="token punctuation">{</span>self<span class="token punctuation">.</span>error_code<span class="token punctuation">}</span></span><span class="token string">&quot;</span></span>
        <span class="token punctuation">]</span>
        <span class="token keyword">if</span> self<span class="token punctuation">.</span>fix_suggestion<span class="token punctuation">:</span>
            parts<span class="token punctuation">.</span>append<span class="token punctuation">(</span><span class="token string-interpolation"><span class="token string">f&quot;修复建议: </span><span class="token interpolation"><span class="token punctuation">{</span>self<span class="token punctuation">.</span>fix_suggestion<span class="token punctuation">}</span></span><span class="token string">&quot;</span></span><span class="token punctuation">)</span>
        parts<span class="token punctuation">.</span>append<span class="token punctuation">(</span>
            <span class="token string">&quot;可重试&quot;</span> <span class="token keyword">if</span> self<span class="token punctuation">.</span>can_retry <span class="token keyword">else</span> <span class="token string">&quot;不建议重试&quot;</span>
        <span class="token punctuation">)</span>
        <span class="token keyword">return</span> <span class="token string">&quot; | &quot;</span><span class="token punctuation">.</span>join<span class="token punctuation">(</span>parts<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>错误类型分类处理</strong>：</p><table><thead><tr><th>错误类型</th><th>可重试</th><th>LLM 应该如何处理</th></tr></thead><tbody><tr><td>网络超时</td><td>是</td><td>重试一次，可能网络波动</td></tr><tr><td>503 服务不可用</td><td>是</td><td>等待后重试，服务可能暂时过载</td></tr><tr><td>401 认证失败</td><td>否</td><td>提示用户检查 API 配置</td></tr><tr><td>422 参数错误</td><td>否</td><td>尝试使用正确的参数格式</td></tr><tr><td>429 频率限制</td><td>是</td><td>等待一段时间后再重试</td></tr><tr><td>500 服务器错误</td><td>是</td><td>可以重试</td></tr></tbody></table><h3 id="_5-2-重试策略的决策权归属" tabindex="-1"><a class="header-anchor" href="#_5-2-重试策略的决策权归属" aria-hidden="true">#</a> 5.2 重试策略的决策权归属</h3><p><strong>核心问题</strong>：重试应该由模型控制还是系统控制？</p><table><thead><tr><th>控制方式</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>模型控制</td><td>灵活，可根据错误类型做决策</td><td>不可预测，可能反复重试失败操作</td></tr><tr><td>系统控制</td><td>确定性强，可以精确限制重试次数</td><td>灵活性差，可能错过可恢复错误</td></tr></tbody></table><p><strong>推荐答案</strong>：系统层控制重试策略。因为 LLM 的行为不可预测，可能在某些情况下反复重试一个注定失败的调用，或者因为一次失败就放弃整个任务。系统层控制可以确保重试行为确定、可控。</p><h3 id="_5-3-典型失败场景解析" tabindex="-1"><a class="header-anchor" href="#_5-3-典型失败场景解析" aria-hidden="true">#</a> 5.3 典型失败场景解析</h3><p><strong>场景一：假装没看到失败</strong></p><ul><li>现象：LLM 收到错误信息后，忽略它并继续往下走</li><li>根因：模型可能把错误信息当作噪声过滤掉了，或者把错误码误解为某种响应内容</li></ul><p><strong>场景二：把失败解读成成功</strong></p><ul><li>现象：模型在错误信息中提取了看似合理的内容并当作成功结果</li><li>根因：训练数据中存在带 &quot;error&quot; 字段但实际返回正常结果的 API，导致模型学会忽略上下文</li></ul><p><strong>场景三：无效参数导致失败，越修越错</strong></p><ul><li>现象：LLM 尝试&quot;修复&quot;参数，但越修越离谱</li><li>根因：模型缺乏对工具 schema 的准确理解，修复往往适得其反</li></ul><h2 id="_6-面试加分项" tabindex="-1"><a class="header-anchor" href="#_6-面试加分项" aria-hidden="true">#</a> 6. 面试加分项</h2><figure><img src="https://imgbed.ppai.top/file/1777162285079_m2-07.jpeg" alt="m2-07.jpeg" tabindex="0" loading="lazy"><figcaption>m2-07.jpeg</figcaption></figure><h3 id="_6-1-展示分层设计思维" tabindex="-1"><a class="header-anchor" href="#_6-1-展示分层设计思维" aria-hidden="true">#</a> 6.1 展示分层设计思维</h3><p><strong>差异化表达</strong>：</p><blockquote><p>“我认为工具执行失败的处理需要分层：工具层负责参数适配和标准化，系统层负责重试策略和错误校验，LLM 层负责根据结构化错误信息做决策——各层职责清晰，避免职责混乱。”</p></blockquote><h3 id="_6-2-展示用户体验考虑" tabindex="-1"><a class="header-anchor" href="#_6-2-展示用户体验考虑" aria-hidden="true">#</a> 6.2 展示用户体验考虑</h3><p><strong>场景化回答</strong>：</p><blockquote><p>“除了技术上正确处理错误，还要考虑用户体验。当工具执行失败时，用户期望看到明确的状态告知，比如&#39;天气服务暂时不可用，可以稍后再试&#39;，而不是一个随机的错误码。”</p></blockquote><h3 id="_6-3-展示边界情况考虑" tabindex="-1"><a class="header-anchor" href="#_6-3-展示边界情况考虑" aria-hidden="true">#</a> 6.3 展示边界情况考虑</h3><p><strong>全面性回答</strong>：</p><blockquote><p>“需要考虑不同错误类型的不同策略：5xx 错误通常可重试，4xx 错误通常不可重试；还要考虑失败窗口期，比如 5 分钟内连续 3 次失败才终止，防止频繁触发失败终止。”</p></blockquote><h3 id="_6-4-展示多工具组合场景" tabindex="-1"><a class="header-anchor" href="#_6-4-展示多工具组合场景" aria-hidden="true">#</a> 6.4 展示多工具组合场景</h3><p><strong>深入思考</strong>：</p><blockquote><p>“如果是多工具任务，其中一个失败了，需要考虑：是直接返回失败，还是尝试其他工具？如何让 LLM 理解部分成功的情况？这涉及到工具���错���的传递机制设计。”</p></blockquote><h2 id="_7-常见面试追问" tabindex="-1"><a class="header-anchor" href="#_7-常见面试追问" aria-hidden="true">#</a> 7. 常见面试追问</h2><figure><img src="https://imgbed.ppai.top/file/1777162284866_m2-08.jpeg" alt="m2-08.jpeg" tabindex="0" loading="lazy"><figcaption>m2-08.jpeg</figcaption></figure><h3 id="q1-为什么模型会把错误当成成功" tabindex="-1"><a class="header-anchor" href="#q1-为什么模型会把错误当成成功" aria-hidden="true">#</a> Q1：为什么模型会把错误当成成功？</h3><p><strong>参考答案</strong>：训练数据中存在大量带 &quot;error&quot; 字段但实际返回正常结果的 API（如错误码在 error 字段但数据在 data 字段），导致模型学会了看到 &quot;error&quot; 字段就提取其中内容，忽略上下文。</p><h3 id="q2-参数自动转换的方案有什么优缺点" tabindex="-1"><a class="header-anchor" href="#q2-参数自动转换的方案有什么优缺点" aria-hidden="true">#</a> Q2：参数自动转换的方案有什么优缺点？</h3><p><strong>参考答案</strong>：优点是减少 LLM 的参数生成负担，提升成功率；缺点是增加了工具层的复杂性，可能掩盖 API 设计问题。</p><h3 id="q3-为什么要设置失败次数上限而不是无限重试" tabindex="-1"><a class="header-anchor" href="#q3-为什么要设置失败次数上限而不是无限重试" aria-hidden="true">#</a> Q3：为什么要设置失败次数上限而不是无限重试？</h3><p><strong>参考答案</strong>：无限重试会导致两个问题：一是用户体验极差，用户等半天得到一个失败结果；二是可能被恶意利用，不断触发重试消耗系统资源。</p><h3 id="q4-重试应该由模型控制还是系统控制" tabindex="-1"><a class="header-anchor" href="#q4-重试应该由模型控制还是系统控制" aria-hidden="true">#</a> Q4：重试应该由模型控制还是系统控制？</h3><p><strong>参考答案</strong>：推荐系统层控制重试策略。因为 LLM 的行为不可预测，系统层控制可以确保重试行为确定、可控。</p><h2 id="_8-总结" tabindex="-1"><a class="header-anchor" href="#_8-总结" aria-hidden="true">#</a> 8. 总结</h2><table><thead><tr><th>考察维度</th><th>核心要点</th></tr></thead><tbody><tr><td>问题描述</td><td>传统 try-catch 不适用，LLM 需要&quot;理解&quot;错误</td></tr><tr><td>典型场景</td><td>忽略错误、误解错误、参数修复越修越错</td></tr><tr><td>解决方案</td><td>参数转换 + 结果校验 + 系统重试 + 失败终止</td></tr><tr><td>工程实现</td><td>分层设计 + 结构化错误信息 + 多级重试策略</td></tr><tr><td>面试话术</td><td>场景化 + 数据化 + 工程化</td></tr></tbody></table><p><strong>一句话总结</strong>：</p><blockquote><p>“工具执行失败处理的核心是分层——工具层减少错误，系统层控制行为，LLM 层做最终决策。面试时，要展示你对 Agent 架构中各层职责的理解，以及在实际项目中的工程落地能力。”</p></blockquote><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料" aria-hidden="true">#</a> 参考资料</h2>`,83),k=n("thead",null,[n("tr",null,[n("th",null,"参考资料"),n("th",null,"访问地址")])],-1),h=n("td",null,"Anthropic Tool Use Guidelines",-1),g={href:"https://docs.anthropic.com/en/docs/tool-use",target:"_blank",rel:"noopener noreferrer"},b=n("td",null,"Agent开发专栏",-1),m={href:"https://ppai.top",target:"_blank",rel:"noopener noreferrer"},v=n("td",null,"Agent工具注册策略：面试高频问题详解",-1),_={href:"https://mp.weixin.qq.com/s/aqSWTUuLaN_mBnuP5q8Pbw",target:"_blank",rel:"noopener noreferrer"},f=n("blockquote",null,[n("p",null,[n("strong",null,"作者"),s("：一灰"),n("br"),n("strong",null,"日期"),s("：2026-04-25"),n("br"),n("strong",null,"标签"),s("： #Agent #面试 #工具执行 #FunctionCalling")])],-1);function y(q,x){const o=e("Mermaid"),t=e("ExternalLinkIcon");return l(),c("div",null,[u,a(o,{id:"mermaid-151",code:""}),d,n("table",null,[k,n("tbody",null,[n("tr",null,[h,n("td",null,[n("a",g,[s("https://docs.anthropic.com/en/docs/tool-use"),a(t)])])]),n("tr",null,[b,n("td",null,[n("a",m,[s("https://ppai.top"),a(t)])])]),n("tr",null,[v,n("td",null,[n("a",_,[s("https://mp.weixin.qq.com/s/aqSWTUuLaN_mBnuP5q8Pbw"),a(t)])])])])]),f])}const L=i(r,[["render",y],["__file","02.Agent工具执行失败：面试高频问题详解.html.vue"]]);export{L as default};
